notification_rules:
  # 工单创建通知
  on_created:
    channels: [slack, pagerduty]
    template: |
      🎫 **工单已创建**: {{ticket_id}}
      **标题**: {{title}}
      **严重性**: {{priority}}
      **集群**: {{cluster}}
      **链接**: {{ticket_url}}

  # 工单升级通知
  on_escalated:
    channels: [slack, pagerduty, sms]
    template: |
      🚨 **工单已升级**: {{ticket_id}}
      **标题**: {{title}}
      **原因**: {{escalation_reason}}
      **等待处理**: {{waiting_time}}
      **链接**: {{ticket_url}}

  # 工单解决通知
  on_resolved:
    channels: [slack]
    template: |
      ✅ **工单已解决**: {{ticket_id}}
      **标题**: {{title}}
      **解决时间**: {{resolution_time}}
      **解决方法**: {{resolution}}
      **验证人**: {{verified_by}}

  # 工单关闭通知
  on_closed:
    channels: []
    template: ""  # 不通知

  # 状态变更通知
  on_status_change:
    # 仅在关键状态变更时通知
    include_statuses: [RESOLVING, VERIFYING, ESCALATED]
    channels: [slack]
    template: |
      📊 **工单状态变更**: {{ticket_id}}
      **新状态**: {{new_status}}
      **变更时间**: {{changed_at}}
